import base64, ctypes as c, io, os, shutil, subprocess, time
from pathlib import Path
from PIL import Image
from pywinauto import Desktop
from pywinauto.keyboard import send_keys
import psutil

ROOT=Path(r"C:\dev\flyExplorer")
EXE=ROOT/"out"/"winui"/"Release"/"flyExplorer.exe"
profile=Path(os.environ["USERPROFILE"])
targets=("Desktop","Documents","Downloads","Pictures","Music","Videos")

def until(fn,why,timeout=25):
    end=time.monotonic()+timeout
    while time.monotonic()<end:
        try:
            value=fn()
            if value:return value
        except Exception:
            pass
        time.sleep(.25)
    raise AssertionError(why)

def screenshot_b64(window):
    img=window.capture_as_image().convert("RGB")
    img.thumbnail((972,720))
    buf=io.BytesIO(); img.save(buf,format="JPEG",quality=84,optimize=True)
    return base64.b64encode(buf.getvalue()).decode("ascii")

def find_auto(root,auto_id):
    for x in root.descendants():
        try:
            if x.element_info.automation_id==auto_id:return x
        except Exception: pass
    return None

def target_rows(root):
    found={}
    for item in root.descendants():
        try:
            if item.element_info.control_type!="ListItem":continue
            name=item.element_info.name or item.window_text()
            for t in targets:
                if t in name:
                    found.setdefault(t,(item,name))
        except Exception:pass
    return found

owned=ROOT/"logs"/"known-folder-artwork-owned"
if owned.exists():shutil.rmtree(owned)
(owned/"localappdata"/"flyExplorer").mkdir(parents=True)
(owned/"localappdata"/"flyExplorer"/"ui-preferences-v1.txt").write_text(
 "schema=2\r\nlanguage=ko-KR\r\ntheme=dark\r\nview=large-icons\r\n",encoding="ascii",newline="")
env=os.environ.copy();env["LOCALAPPDATA"]=str(owned/"localappdata")
proc=subprocess.Popen([str(EXE),str(profile)],cwd=EXE.parent,env=env)
appwin=None
try:
    appwin=until(lambda: next((x for x in Desktop(backend="uia").windows(process=proc.pid)
                              if "flyExplorer" in x.window_text()),None),
                 "flyExplorer window unavailable")
    try:appwin.move_window(x=40,y=40,width=972,height=720,repaint=True)
    except Exception:pass
    left=until(lambda:find_auto(appwin,"LeftFiles"),"LeftFiles UIA missing")
    rows=until(lambda:(lambda x:x if len(x)>=6 else None)(target_rows(left)),
               "six Known Folder rows unavailable",30)
    time.sleep(1)
    print("FLY_KNOWN_FOLDER_COUNT",len(rows),flush=True)
    for t in targets:
        item,name=rows[t]
        imgs=[x for x in item.descendants()
              if x.element_info.control_type=="Image" and
                 x.element_info.name=="Windows Known Folder artwork"]
        r=item.rectangle()
        print("FLY_KNOWN_FOLDER_ROW",t,repr(name),r.left,r.top,r.width(),r.height(),
              "ARTWORK_IMAGES",len(imgs),flush=True)
        if len(imgs)!=1:raise AssertionError(f"{t}: artwork image count {len(imgs)}")
    print("FLY_SCREENSHOT_BEGIN",flush=True);print(screenshot_b64(appwin),flush=True);print("FLY_SCREENSHOT_END",flush=True)
finally:
    if proc.poll() is None:
        if appwin:c.windll.user32.PostMessageW(appwin.handle,0x10,0,0)
        try:proc.wait(timeout=10)
        except subprocess.TimeoutExpired:proc.terminate();proc.wait(timeout=8)
print("FLY_PROCESS_EXIT",proc.returncode,flush=True)

before=set()
for w in Desktop(backend="uia").windows(control_type="Window"):
    try:
        if psutil.Process(w.element_info.process_id).name().lower()=="explorer.exe":before.add(w.handle)
    except Exception:pass
subprocess.Popen(["explorer.exe","/separate,",str(profile)])
expwin=None
try:
    def get_exp():
        for w in Desktop(backend="uia").windows(control_type="Window"):
            try:
                if w.handle in before:continue
                if psutil.Process(w.element_info.process_id).name().lower()=="explorer.exe":return w
            except Exception:pass
        return None
    expwin=until(get_exp,"new Explorer window unavailable",20)
    try:expwin.move_window(x=40,y=40,width=972,height=720,repaint=True)
    except Exception:pass
    expwin.set_focus();send_keys("^+2");time.sleep(1.5)
    erows=until(lambda:(lambda x:x if len(x)>=6 else None)(target_rows(expwin)),
                "Explorer Known Folder rows unavailable",20)
    print("EXPLORER_KNOWN_FOLDER_COUNT",len(erows),flush=True)
    for t in targets:
        item,name=erows[t];r=item.rectangle()
        print("EXPLORER_KNOWN_FOLDER_ROW",t,repr(name),r.left,r.top,r.width(),r.height(),flush=True)
    print("EXPLORER_SCREENSHOT_BEGIN",flush=True);print(screenshot_b64(expwin),flush=True);print("EXPLORER_SCREENSHOT_END",flush=True)
finally:
    if expwin:
        try:expwin.close()
        except Exception:pass

